param([int[]]$Scenarios=@(1,3,5,10),[int]$BasePort=0)
$ErrorActionPreference='Stop';$repo=Split-Path $PSScriptRoot;$mvn="$env:USERPROFILE\.m2\wrapper\dists\apache-maven-3.9.12-bin\5nmfsn99br87k5d4ajlekdq10k\apache-maven-3.9.12\bin\mvn.cmd";$ff=(Get-ChildItem "$env:TEMP\transcoder-ffmpeg-portable-qa" -Recurse -Filter ffmpeg.exe|Select -First 1).FullName;$fp=(Get-ChildItem "$env:TEMP\transcoder-ffmpeg-portable-qa" -Recurse -Filter ffprobe.exe|Select -First 1).FullName;$video=Join-Path $env:TEMP 'youtube-unit-qa-videos\v480.mp4';$root=Join-Path $env:TEMP 'youtube-unit-concurrency-final3';New-Item -ItemType Directory -Force $root|Out-Null;$all=@()
foreach($n in $Scenarios){$port=if($BasePort){$BasePort+$n}else{(Get-Random -Minimum 20000 -Maximum 40000)};$dir=Join-Path $root "clients-$n";New-Item -ItemType Directory -Force $dir|Out-Null;$summary=[ordered]@{clients=$n;port=$port;stage='startup';http202=0;http429=0;otherHttp=0;completed=0;failed=0;timeout=0;durationMs=0;result='FAIL';reason=$null};$api=$null;$old=@{PORT=$env:PORT;TRANSCODER_DATA_DIR=$env:TRANSCODER_DATA_DIR;FFMPEG_BIN=$env:FFMPEG_BIN;FFPROBE_BIN=$env:FFPROBE_BIN};try{$data=Join-Path $dir data;New-Item -ItemType Directory -Force $data|Out-Null;$env:PORT="$port";$env:TRANSCODER_DATA_DIR=$data;$env:FFMPEG_BIN=$ff;$env:FFPROBE_BIN=$fp;$api=Start-Process $mvn -ArgumentList 'exec:java' -WorkingDirectory $repo -RedirectStandardOutput (Join-Path $dir api.log) -RedirectStandardError (Join-Path $dir api.err) -PassThru;$ready=$false;for($i=0;$i-lt 60;$i++){try{if((Invoke-RestMethod "http://127.0.0.1:$port/health").status -eq 'UP' -and @(Invoke-RestMethod "http://127.0.0.1:$port/jobs").Count -eq 0){$ready=$true;break}}catch{};Start-Sleep -Milliseconds 300};if(!$ready){throw 'startup timeout'};$summary.stage='upload';$barrier=Join-Path $dir START;$jobs=1..$n|%{Start-Job -ArgumentList $port,$video,$barrier,$_ -ScriptBlock {param($p,$f,$b,$i)while(!(Test-Path $b)){Start-Sleep -Milliseconds 10};$x=& curl.exe -sS -w "`nHTTP:%{http_code}" -X POST -F "file=@$f;type=video/mp4" -F "origin=cliente-$i" -F 'permission=sintetico' -F 'profiles=360p' "http://127.0.0.1:$p/videos" 2>&1;[pscustomobject]@{i=$i;raw=($x -join "`n")}}};New-Item $barrier -ItemType File|Out-Null;$sw=[Diagnostics.Stopwatch]::StartNew();$res=$jobs|Receive-Job -Wait -AutoRemoveJob;$summary.durationMs=$sw.ElapsedMilliseconds;$res|ConvertTo-Json -Depth 4|Set-Content (Join-Path $dir responses.json);$ids=@();foreach($r in $res){if($r.raw -match 'HTTP:(\d+)'){if($Matches[1]-eq '202'){$summary.http202++}elseif($Matches[1]-eq '429'){$summary.http429++}else{$summary.otherHttp++}}$m=[regex]::Match($r.raw,'"id":"([^"]+)"');if($m.Success){$ids+=$m.Groups[1].Value}};$summary.stage='poll';$states=@{};for($k=0;$k-lt 120 -and ($states.Values|? {$_ -in @('QUEUED','PROCESSING')}).Count -gt 0 -or ($k -eq 0 -and $ids.Count -gt 0);$k++){foreach($id in $ids){if(!$states.ContainsKey($id)-or $states[$id] -in @('QUEUED','PROCESSING')){$j=Invoke-RestMethod "http://127.0.0.1:$port/jobs/$id";$states[$id]=$j.status}};if($states.Count -eq $ids.Count -and ($states.Values|? {$_ -in @('QUEUED','PROCESSING')}).Count -eq 0){break};Start-Sleep -Milliseconds 500};$summary.completed=($states.Values|? {$_ -eq 'COMPLETED'}).Count;$summary.failed=($states.Values|? {$_ -eq 'FAILED'}).Count;$summary.timeout=$ids.Count-$states.Count;$summary.stage='validated';if($summary.http202+$summary.http429+$summary.otherHttp -eq $n -and $summary.completed -eq $summary.http202 -and $summary.failed -eq 0 -and $summary.timeout -eq 0){$summary.result='PASS'}else{throw "criteria failed"}}catch{ $summary.reason=$_.Exception.Message; $summary.result='FAIL'}finally{$summary|ConvertTo-Json|Set-Content (Join-Path $dir summary.json);$all+=[pscustomobject]$summary;if($api -and !$api.HasExited){& taskkill.exe /PID $api.Id /T /F 2>$null|Out-Null};$env:PORT=$old.PORT;$env:TRANSCODER_DATA_DIR=$old.TRANSCODER_DATA_DIR;$env:FFMPEG_BIN=$old.FFMPEG_BIN;$env:FFPROBE_BIN=$old.FFPROBE_BIN}};$all|ConvertTo-Json|Set-Content (Join-Path $root summary.json);$all|ConvertTo-Json -Compress|Write-Output;if(($all|? result -ne 'PASS').Count){exit 1}else{exit 0}
